#!/usr/bin/env bash
# recipes/crate-security-framework-sys--2-9-1/build.sh -- stage the security-framework-sys 2.9.1 crate as
# an entry of the cargo directory source share/cargo/crates/ (docs/rust-crates.md).
# Generated by tools/make_crate_packages.py.
set -euo pipefail
dest="${CVC_INSTALL_DIR}/share/cargo/crates/security-framework-sys-2.9.1"
mkdir -p "${dest}"
cp -R "${CVC_SOURCE_DIR}/." "${dest}/"
# cargo reads a directory-source entry's checksums from here. "package" is the
# Cargo.lock checksum, which cargo compares; no per-file hashes (the bundle's
# own sha256 covers the files).
printf '{"files":{},"package":"e932934257d3b408ed8f30db49d85ea163bfe74961f017f405b025af298f0c7a"}\n' > "${dest}/.cargo-checksum.json"
